import{_ as o,l as i,o as e,c as l,v as t,p as s,x as r,d as E,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"颤抖手完美","description":"","frontmatter":{"title":"颤抖手完美","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/trembling-hand.md","filePath":"econ/trembling-hand.md","lastUpdated":1789023840000}'),h={name:"econ/trembling-hand.md"};function m(A,a,B,c,_,P){const n=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="颤抖手完美" tabindex="-1">颤抖手完美 <a class="header-anchor" href="#颤抖手完美" aria-label="Permalink to &quot;颤抖手完美&quot;">​</a></h1><div class="epigraph"><p>完美性要求均衡是完全混合扰动博弈之纳什的极限：每只手都以任意小的概率发抖，于是每个信息集都会被碰到。</p><footer>—— Selten, Reexamination of the Perfectness Concept for Equilibrium Points in Extensive Games, International Journal of Game Theory, 1975</footer></div><p><a href="/econ/subgame-perfect">上一课</a>用子博弈完美删掉「到达之后自己也不愿执行」的威胁。缺口是：许多信息集根本开不出子博弈——不完美信息、非单点信息集，SPE 管不到。Selten 1975 的颤抖手更强：让每人在每个信息集上以至少 \\(\\varepsilon\\) 的概率误触每一行动，再令 \\(\\varepsilon\\to 0\\)，极限均衡必须在这些「几乎不到」的点上仍近似最优。本课钉完美均衡，不把蜈蚣的认知悖论提前，也不重写逆向归纳算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>策略式里，纳什可以靠弱劣策略撑住：若对手绝不走进某列，自己在该列上的亏本招不会被罚。扩展式里，这就是空威胁。SPE 只在子博弈（单点、切得干净）上要求纳什；信息集若跨枝，没有子博弈可切。</p><p>颤抖手完美：存在一列完全混合策略 \\(\\sigma^k\\) 与一列 \\(\\varepsilon_k\\to 0\\)，使 \\(\\sigma^k\\) 是「每行动概率至少 \\(\\varepsilon_k\\)」的扰动博弈的纳什，且 \\(\\sigma^k\\to\\sigma^*\\)。极限 \\(\\sigma^*\\) 是原博弈的完美均衡。因为扰动下每个信息集正概率到达，最优反应必须在那些点上也成立——不可信的亏本招在极限里活不下来。</p><h3 id="完美比-spe-窄-不是另一套支付" tabindex="-1">完美比 SPE 窄，不是另一套支付 <a class="header-anchor" href="#完美比-spe-窄-不是另一套支付" aria-label="Permalink to &quot;完美比 SPE 窄，不是另一套支付&quot;">​</a></h3><p>有限扩展式上，完美均衡一定是 SPE；反过来不必。进入遏制里，「进入 / 斗争」可以是纳什（进入者不进），不是 SPE，更不是完美。完美信息、支付无平局时，逆向归纳路径常常既是 SPE 也是完美；平局或弱劣一开，两者分开。</p><p><span class="marginnote">策略式完美均衡不含弱劣策略。扩展式要先取行为策略再扰动，不能只在摊平后的策略式上删弱劣——摊平会把「在未达信息集上的规定」与「路径上的规定」绑成同一个纯策略，扰动的含义不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：有限博弈，完美回忆。先在策略式上写：完美 \\(=\\) 完全混合纳什的极限。再搬到树上：对每个信息集的行为策略加最小概率扰动（Selten 的 agent-normal form：把每一信息集当成一个代理人）。不在本课解序贯均衡的信念系统；Kreps–Wilson 用「信念 + 序贯理性」重写同一直觉，主干后课才用。</p>',11)),(e(),s(d,null,{default:r(()=>[p(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NE%5B%22%E7%AD%96%E7%95%A5%E5%BC%8F%E7%BA%B3%E4%BB%80%22%5D%20--%3E%20SPE%5B%22SPE%EF%BC%9A%E6%AF%8F%E4%B8%AA%E5%AD%90%E5%8D%9A%E5%BC%88%E6%98%AF%E7%BA%B3%E4%BB%80%22%5D%0A%20%20SPE%20--%3E%20TH%5B%22%E9%A2%A4%E6%8A%96%E6%89%8B%EF%BC%9A%E6%89%B0%E5%8A%A8%E5%90%8E%E4%BB%8D%E8%BF%91%E4%BC%BC%E7%BA%B3%E4%BB%80%22%5D%0A%20%20TH%20--%3E%20REACH%5B%22%E6%AF%8F%E4%B8%AA%E4%BF%A1%E6%81%AF%E9%9B%86%E6%AD%A3%E6%A6%82%E7%8E%87%E5%88%B0%E8%BE%BE%22%5D%0A%20%20REACH%20--%3E%20DROP%5B%22%E5%BC%B1%E5%8A%A3%20%2F%20%E7%A9%BA%E5%A8%81%E8%83%81%E5%9C%A8%E6%9E%81%E9%99%90%E4%B8%AD%E6%B6%88%E5%A4%B1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>检验：若某策略在某个正概率被碰到的信息集上不是最优反应，则对足够小的 \\(\\varepsilon\\) 它也不是扰动博弈的纳什，故不能进入极限。这比「只在子博弈根上检查」更密。两人同时选「合作 / 互毁」而互毁弱劣时，纳什可以靠「对方会互毁」撑住；完全混合扰动里互毁严格吃亏，极限只留下合作。进入博弈是同一把刀的扩展式版。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>发抖把「未达」变成「稀有事件」。惩罚者若在该事件里吃亏，扰动下他会改招，进入者预见到这一点，空威胁从均衡里掉出去。可信性不再靠建模者指定子博弈，而靠技术条件：完全混合逼近。</p><p>与<a href="/econ/mixed-strategy">混合策略</a>的差别：混合是原博弈里的随机化，用来让对手无差异；颤抖是建模者加的失误，用来挑选哪些纳什在极限里站得住。均衡策略本身可以是纯的，只要它是某列失误均衡的极限。Myerson 的适当均衡（proper）还要求更差的失误相对更稀有，本课停在 Selten 的 \\(\\varepsilon\\)-完美。</p><p>策略式上先扰动再取极限，与树上对每个信息集分别发抖，筛选可以不同：摊平后的一个纯策略捆住了许多信息集上的规定，弱劣删除会误伤或漏删。Selten 因此强调 agent form——每个信息集一个代理人，失误彼此独立。课堂上以扩展式为准。</p><h3 id="扰动必须落在行为上" tabindex="-1">扰动必须落在行为上 <a class="header-anchor" href="#扰动必须落在行为上" aria-label="Permalink to &quot;扰动必须落在行为上&quot;">​</a></h3><p>若只扰动终点支付、不扰动行动，弱劣仍可能留下。Selten 的对象是策略的最小概率，不是支付的连续统扰动（那是本质均衡一类）。课堂上用进入博弈与「双方都准备合作、但合同写了互毁」核对：互毁若弱劣，完美不要它。</p><p><span class="marginnote">完美信息有限树上，SPE 与完美常常重合；需要颤抖手出刀的，多半是不完美信息或弱劣撑着的纳什。后课逆向归纳的限度问的是另一件事：共同知识理性推不推得出未达节点上的理性。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>无限行动、连续型要另写扰动；本课有限。完美仍可能很怪：信号博弈里，对偏离的解释可以靠「特定方向的失误」，直觉标准还要再砍。适当均衡、序贯均衡、完美贝叶斯是后继精炼，不是本课的算法。</p><p>也不要把颤抖手写成宏观政策「承诺要留失误余地」。本课只是均衡精炼：缩小纳什集，不改支付。</p><p>连续行动要把「每个纯策略正概率」改成对全支撑的扰动，技术更重，直觉不变：未达集合必须被碰到。本课有限已经够用：SPE 删空威胁，颤抖手在信息集切不干净时接着删。</p><p>后课默认：需要每个信息集都被碰到时，解概念从 SPE 升级为颤抖手完美；SPE 是必要条件。认知上「未达节点还有没有理性」，是下一课逆向归纳的限度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SPE 只管子博弈；颤抖手让每个信息集以任意小概率被碰到。</li><li>完美均衡是完全混合扰动纳什的极限，剔除靠弱劣撑住的空威胁。</li><li>完美 \\(\\Rightarrow\\) SPE；有限完美信息上两者常常重合。</li><li>发抖是选择均衡的技术，不是玩家真的随机化。</li><li>出处：Selten, <em>IJGT</em>, 1975。</li></ul>',15))])}const u=o(h,[["render",m]]);export{f as __pageData,u as default};
